gai0(){return"\u0645\u0631\u062d\u0644\u0629 \u062a\u0641\u0631\u064a\u0642 \u0627\u0644\u062a\u0635\u0646\u064a\u0639"},
gai_(){return"\u0639\u0646\u062f \u0645\u0633\u062d \u0637\u0644\u0628 \u0645\u062a\u0639\u062f\u062f \u0627\u0644\u0623\u0646\u0648\u0627\u0639 \u0644\u0644\u0627\u0646\u062a\u0642\u0627\u0644 \u0625\u0644\u0649 \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u062d\u0644\u0629 (\u0623\u0648 \u0645\u0646\u0647\u0627)\u060c \u062a\u0646\u062a\u0642\u0644 \u0641\u0642\u0637 \u0627\u0644\u0648\u062d\u062f\u0627\u062a \u0627\u0644\u062a\u064a \u062a\u0637\u0627\u0628\u0642 \u0645\u0627\u062f\u062a\u0647\u0627 \u0645\u0643\u064a\u0646\u0629 \u0627\u0644\u0641\u0646\u064a \u0627\u0644\u0630\u064a \u0645\u0633\u062d. \u0641\u0639\u0651\u0644 \u0647\u0630\u0627 \u0639\u0644\u0649 \u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0643\u0628\u0633/\u0627\u0644\u062e\u0631\u0627\u0637\u0629."},
gahc(){return"\u0645\u0633\u0627\u0631 \u0627\u0644\u062a\u0635\u0646\u064a\u0639"},
gahb(){return"\u0639\u0646\u062f \u0645\u0631\u062d\u0644\u0629 \u062a\u0641\u0631\u064a\u0642 \u0627\u0644\u062a\u0635\u0646\u064a\u0639\u060c \u0645\u0633\u062d \u0647\u0630\u0627 \u0627\u0644\u0641\u0646\u064a \u0641\u0642\u0637 \u064a\u0646\u0642\u0644 \u0627\u0644\u0648\u062d\u062f\u0627\u062a \u0627\u0644\u062a\u064a \u062a\u0633\u062a\u062e\u062f\u0645 \u0647\u0630\u0647 \u0627\u0644\u0645\u0627\u062f\u0629 \u0641\u064a \u0627\u0644\u0637\u0644\u0628 \u0627\u0644\u0645\u062a\u0639\u062f\u062f \u0627\u0644\u0623\u0646\u0648\u0627\u0639."},
