ga3o(){return"\u0647\u06d5\u0698\u0645\u0627\u0631\u06d5\u06a9\u06d5\u0645"},
ga3p(){return"\u0626\u06cc\u0645\u06d5\u06cc\u0644 \u0648 \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc\u06cc \u0686\u0648\u0648\u0646\u06d5\u0698\u0648\u0648\u0631\u06d5\u0648\u06d5\u062a."},
