al6(a){return"\u0628\u0646\u06d5\u0695\u06d5\u062a\u06cc "+a},
gala(){return"\u0628\u0646\u06d5\u0695\u06d5\u062a\u06cc"},
gal9(){return"\u06cc\u06d5\u06a9\u06d5\u06cc \u06cc\u06d5\u06a9\u06d5\u0645"},
