ald(a){return""+a+" \u0644\u06d5 \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646\u06cc \u0626\u06d5\u0645 \u067e\u0632\u06cc\u0634\u06a9\u06d5 \u0646\u0631\u062e\u06cc\u0627\u0646 \u062f\u06d5\u06af\u06c6\u0695\u06ce\u062a \u0628\u06d5 \u0646\u0631\u062e\u06d5 \u0646\u0648\u06ce\u06cc\u06d5\u06a9\u06d5. \u0646\u06cc\u0634\u0627\u0646\u06d5\u06cc \u0647\u06d5\u0631 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9 \u0644\u0627\u0628\u06d5 \u0628\u06c6 \u0626\u06d5\u0648\u06d5\u06cc \u0646\u0631\u062e\u06cc \u0626\u06ce\u0633\u062a\u0627\u06cc \u0628\u0645\u06ce\u0646\u06ce\u062a. \u06a9\u06d5\u06cc\u0633\u06cc \u067e\u0627\u0631\u06d5\u062f\u0631\u0627\u0648\u060c \u062f\u0648\u0648\u0628\u0627\u0631\u06d5\u06a9\u0631\u0627\u0648\u06d5 \u0648 \u0647\u06d5\u06b5\u0648\u06d5\u0634\u0627\u0648\u06d5 \u0647\u06d5\u0631\u06af\u06cc\u0632 \u0646\u0627\u06af\u06c6\u0695\u06ce\u0646."},
gale(){return"\u062a\u06d5\u0646\u0647\u0627 \u06a9\u06d5\u06cc\u0633\u06d5 \u0646\u0648\u06ce\u06cc\u06d5\u06a9\u0627\u0646"},
alb(a){return"\u0646\u0648\u06ce\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc "+a+" \u06a9\u06d5\u06cc\u0633"},
alc(a){return"\u0646\u0631\u062e\u06cc "+a+" \u06a9\u06d5\u06cc\u0633 \u0646\u0648\u06ce\u06a9\u0631\u0627\u06cc\u06d5\u0648\u06d5"},
ame(a){return"\u0695\u06ce\u0698\u06d5\u06cc \u06a9\u06c6\u0645\u06cc\u0633\u06cc\u06c6\u0646 \u2014 "+a},
