gamg(){return"\u0628\u0695\u06ce\u06a9 \u06cc\u0627\u0646 \u0695\u06ce\u0698\u06d5\u06cc\u06d5\u06a9 \u0628\u0646\u0648\u0648\u0633\u06d5"},
gamx(){return"\u0628\u06d5\u067e\u06ce\u06cc \u062f\u06a9\u062a\u06c6\u0631"},
